import{_ as r,o as e,c as d,ak as a}from"./chunks/framework.CMX7UUIo.js";const p=JSON.parse('{"title":"什么是次粉？","description":"","frontmatter":{"title":"什么是次粉？"},"headers":[],"relativePath":"crops/wheat/Midds/index.md","filePath":"crops/wheat/Midds/index.md"}'),s={name:"crops/wheat/Midds/index.md"};function n(o,t,h,i,l,c){return e(),d("div",null,[...t[0]||(t[0]=[a('<h1 id="次粉" tabindex="-1">次粉 <a class="header-anchor" href="#次粉" aria-label="Permalink to “次粉”">​</a></h1><p>次粉，又称黑面、黄粉、下面、三等粉等，是小麦加工过程中产生的副产物。由种皮、果皮、糊粉层、胚及部分胚乳组成，富含蛋白质、膳食纤维、维生素和矿物质，淀粉含量约30%，产量约占小麦籽粒总量的4%。其蛋白质含量为12.5%-17%，主要由清蛋白、球蛋白、麦胶蛋白和麦谷蛋白构成</p><h2 id="质量指标" tabindex="-1">质量指标 <a class="header-anchor" href="#质量指标" aria-label="Permalink to “质量指标”">​</a></h2><p>次粉按照灰分含量一般分为：<strong>2.5次粉</strong>、<strong>3.0次粉</strong>、<strong>4.0次粉</strong>，分别对应国标文件<a href="https://std.samr.gov.cn/hb/search/stdHBDetailed?id=F997A516CB591C94E05397BE0A0A70DA" target="_blank" rel="noreferrer">NY/T 211-2023</a>中的<strong>一级</strong>、<strong>二级</strong>、<strong>三级</strong>指标。根据厂家需求不同，也会有3.5次粉、4.5次粉等各种灰分含量不同的次粉。</p><table><thead><tr><th>质量标准</th><th>一级</th><th>二级</th><th>三级</th></tr></thead><tbody><tr><td>粗纤维/%</td><td>≤3.5</td><td>≤5.5</td><td>≤7.0</td></tr><tr><td>灰分含量/% </td><td>≤2.5</td><td>≤3.0</td><td>≤4.0</td></tr><tr><td>粗蛋白/%</td><td colspan="3">≥13.0</td></tr><tr><td>水分含量/%</td><td colspan="3">≤13.5</td></tr></tbody></table>',5)])])}const g=r(s,[["render",n]]);export{p as __pageData,g as default};
